import numpy as np
class Quaternion:
    def __init__(self, w, x, y, z):
        self.q = np.array([w, x, y, z])

    def normalize(self):
        norm = np.linalg.norm(self.q)
        self.q = self.q / norm
        return self

    def multiply(self, other):
        w = self.q[0]*other.q[0] - self.q[1]*other.q[1] - self.q[2]*other.q[2] - self.q[3]*other.q[3]
        x = self.q[0]*other.q[1] + self.q[1]*other.q[0] + self.q[2]*other.q[3] - self.q[3]*other.q[2]
        y = self.q[0]*other.q[2] - self.q[1]*other.q[3] + self.q[2]*other.q[0] + self.q[3]*other.q[1]
        z = self.q[0]*other.q[3] + self.q[1]*other.q[2] - self.q[2]*other.q[1] + self.q[3]*other.q[0]
        return Quaternion(w,x,y,z)

