def slerp(q0, q1, t):
    cosθ = np.dot(q0.q, q1.q)
    if cosθ < 0:
        q1.q = -q1.q
        cosθ = -cosθ
    θ = np.arccos(cosθ)
    sinθ = np.sin(θ)
    if abs(sinθ) < 1e-6:
        return q0
    w0 = np.sin((1-t)*θ)/sinθ
    w1 = np.sin(t*θ)/sinθ
    return Quaternion(*((w0*q0.q + w1*q1.q).tolist())).normalize()

import numpy as np

def tensor_frobenius_norm(tensor):
    return np.sqrt(np.sum(tensor**2))

def unfold(tensor, mode=0):
    return np.reshape(
        np.moveaxis(tensor, mode, 0),
        (tensor.shape[mode], -1)
    )

# Example usage:
if __name__ == "__main__":
    tensor = np.random.rand(3,4,5)
    print(f"Frobenius norm: {tensor_frobenius_norm(tensor):.2f}")
    print(f"Mode-0 unfolding shape: {unfold(tensor, 0).shape}")
